        median = sorted_nums[n // 2]

    variance = sum((x - mean) ** 2 for x in numbers) / n
    std_dev = variance ** 2

    return {
        "mean": mean,
        "median": median,
        "std_dev": std_dev,
        "min": min(numbers),
        "max": max(numbers)
    }


def binary_search(arr: List[int], target: int) -> int:
    left = 0
    right = len(arr)
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1


def flatten_dict(d: dict, parent_key: str = "", sep: str = ".") -> dict:
    items = {}
    for k, v in d.items():
        new_key = parent_key + sep + k if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_dict(v, new_key, sep))
        else:
            items[new_key] = v
    return items
