import pytest
from file_processor import read_file, write_file, count_words, find_files, process_all_files
import os
import tempfile

def test_read_file_normal_case():
    with tempfile.NamedTemporaryFile(mode='w') as tmp:
        tmp.write('Hello World')
        tmp.flush()
        assert read_file(tmp.name) == 'Hello World'

def test_read_file_edge_case_empty_file():
    with tempfile.NamedTemporaryFile(mode='w') as tmp:
        tmp.write('')
        tmp.flush()
        assert read_file(tmp.name) == ''

def test_read_file_edge_case_non_existent_file():
    with pytest.raises(FileNotFoundError):
        read_file('non_existent_file.txt')

def test_write_file_normal_case():
    with tempfile.NamedTemporaryFile(mode='w') as tmp:
        write_file(tmp.name, 'Hello World')
        tmp.seek(0)
        assert tmp.read() == 'Hello World'

def test_write_file_edge_case_empty_content():
    with tempfile.NamedTemporaryFile(mode='w') as tmp:
        write_file(tmp.name, '')
        tmp.seek(0)
        assert tmp.read() == ''

def test_count_words_normal_case():
    assert count_words('Hello World') == 2

def test_count_words_edge_case_empty_string():
    assert count_words('') == 0

def test_count_words_edge_case_single_word():
    assert count_words('Hello') == 1

def test_count_words_edge_case_multiple_spaces():
    assert count_words('Hello   World') == 2

def test_find_files_normal_case():
    with tempfile.TemporaryDirectory() as tmpdir:
        with open(os.path.join(tmpdir, 'file1.txt'), 'w') as f:
            f.write('Hello World')
        with open(os.path.join(tmpdir, 'file2.txt'), 'w') as f:
            f.write('Hello World')
        assert find_files(tmpdir, '.txt') == ['file1.txt', 'file2.txt']

def test_find_files_edge_case_empty_directory():
    with tempfile.TemporaryDirectory() as tmpdir:
        assert find_files(tmpdir, '.txt') == []

def test_find_files_edge_case_non_existent_directory():
    assert find_files('non_existent_directory', '.txt') == []

def test_process_all_files_normal_case():
    with tempfile.TemporaryDirectory() as tmpdir:
        with open(os.path.join(tmpdir, 'file1.txt'), 'w') as f:
            f.write('Hello World')
        with open(os.path.join(tmpdir, 'file2.txt'), 'w') as f:
            f.write('Hello World')
        assert process_all_files(tmpdir) == {'file1.txt': 2, 'file2.txt': 2}

def test_process_all_files_edge_case_empty_directory():
    with tempfile.TemporaryDirectory() as tmpdir:
        assert process_all_files(tmpdir) == {}

def test_process_all_files_edge_case_non_existent_directory():
    assert process_all_files('non_existent_directory') == {}

